  pinMode(LED_BUILTIN, OUTPUT);    // First tell the chip: I'm using this pin as an output
}

void loop() {
  digitalWrite(LED_BUILTIN, HIGH); // Output HIGH (3.3V or 5V)
  delay(500);                      // Dumb-wait 500 milliseconds; the chip can't do anything else meanwhile
  digitalWrite(LED_BUILTIN, LOW);  // Output LOW (0V)
  delay(500);
