#include <Arduino.h>
// One leg of the button to PB12, the other to GND. Using the chip's internal pull-up: not pressed = HIGH, pressed = LOW
const int BTN = PB12;
const int LED = PC13;
const unsigned long DEBOUNCE_MS = 30;  // Mechanical bounce usually settles within 5~20ms

int lastReading = HIGH;         // Previous raw reading
int stableState = HIGH;         // The debounced state we actually trust
unsigned long lastChange = 0;   // When the raw reading last changed
unsigned long pressCount = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);   // Internal pull-up saves a resistor
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  int reading = digitalRead(BTN);
  if (reading != lastReading) {   // Raw reading changed: restart the timer
    lastChange = millis();
    lastReading = reading;
  }
  // Only trust the reading once it has stayed the same for longer than DEBOUNCE_MS
  if (millis() - lastChange > DEBOUNCE_MS && reading != stableState) {
    stableState = reading;
    if (stableState == LOW) {     // Count only at the instant of "just pressed"
      pressCount++;
      Serial.print("Press count: ");
      Serial.println(pressCount);
    }
  }
  digitalWrite(LED, stableState); // When pressed (LOW), PC13 goes low and the LED lights
}

#include <Arduino.h>
// Button on PB12 to GND, internal pull-up. Each press flips the LED state
const int BTN = PB12;
const int LED = PC13;

bool ledOn = false;             // The "current state" we remember ourselves
int lastStable = HIGH;          // Last accepted button state
int lastReading = HIGH;
unsigned long lastChange = 0;

void setup() {
  pinMode(BTN, INPUT_PULLUP);
  pinMode(LED, OUTPUT);
  digitalWrite(LED, HIGH);      // PC13 HIGH = off
}

void loop() {
  int reading = digitalRead(BTN);
  if (reading != lastReading) { lastChange = millis(); lastReading = reading; }

  if (millis() - lastChange > 30 && reading != lastStable) {
    lastStable = reading;
    if (lastStable == LOW) {    // Detect the "falling edge": the instant it goes from not pressed to pressed
      ledOn = !ledOn;           // Flip the state
      digitalWrite(LED, ledOn ? LOW : HIGH);  // PC13 lights on LOW
    }
  }
}

#include <Arduino.h>
// External LED: PA8 → 220Ω resistor → LED long leg, LED short leg → GND
// The PC13 onboard LED has no timer behind it, so analogWrite does nothing there; that's why we add an external one
const int LED = PA8;

void setup() {
  pinMode(LED, OUTPUT);
  analogWriteFrequency(1000);   // STM32duino-specific: PWM frequency 1kHz, no visible flicker
  analogWriteResolution(8);     // 0~255, 256 levels
}

void loop() {
  for (int duty = 0; duty <= 255; duty++) {   // Fade in
    analogWrite(LED, duty);   // duty=0 fully off, 255 fully on, 128 roughly half
    delay(4);
  }
  for (int duty = 255; duty >= 0; duty--) {   // Fade out
    analogWrite(LED, duty);
    delay(4);
  }
}
