#include <Arduino.h>
// Potentiometer: outer legs to 3.3V and GND, middle leg to PA0
const int POT = PA0;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);  // The STM32 ADC is 12-bit: 0~4095 (default gives 10-bit, 0~1023)
}

void loop() {
  int raw = analogRead(POT);

  // map(value, fromLow, fromHigh, toLow, toHigh): convert 0~4095 to 0~100
  int percent = map(raw, 0, 4095, 0, 100);

  // Convert to volts: raw / 4095 * 3.3V. Use float and 3.3f, otherwise integer division gives all zeros
  float volts = raw * 3.3f / 4095.0f;

  Serial.print("raw=");
  Serial.print(raw);
  Serial.print("  ");
  Serial.print(percent);
  Serial.print("%  ");
  Serial.print(volts, 2);    // Two decimal places
  Serial.println("V");
  delay(200);
}

#include <Arduino.h>
// In the serial monitor type on / off / ? and press Enter (set the monitor to "send newline \n")
// The Blue Pill's Serial is PA9(TX)/PA10(RX) and needs a USB-TTL adapter; Nucleo/UNO/ESP32 use USB directly
String cmd = "";

void handle(String c) {
  c.trim();                  // Strip spaces and CR/LF from both ends
  if (c == "on")       digitalWrite(LED_BUILTIN, HIGH);
  else if (c == "off") digitalWrite(LED_BUILTIN, LOW);
  else if (c == "?")   Serial.println("Commands: on off ?");
  else { Serial.print("Unknown: "); Serial.println(c); return; }
  Serial.print("OK ");
  Serial.println(c);
}

void setup() {
  Serial.begin(115200);      // The baud rate must match monitor_speed in platformio.ini
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.println("Ready. Type on / off / ? and press Enter");
}

void loop() {
  while (Serial.available()) {          // Pull bytes out while the buffer has any
    char ch = Serial.read();
    if (ch == '\n') {                   // A newline means one complete command
      handle(cmd);
      cmd = "";
    } else if (cmd.length() < 32) {     // Length limit so random typing can't blow up memory
      cmd += ch;
    }
  }
}

#include <Arduino.h>
// Two jobs at their own pace: the LED toggles every 250ms, serial reports a heartbeat every 2 seconds
// Core idea: don't "wait"; instead, every pass ask "is it time yet?"

unsigned long lastBlink = 0;
unsigned long lastReport = 0;
const unsigned long BLINK_MS = 250;
const unsigned long REPORT_MS = 2000;
bool ledState = false;
unsigned long loops = 0;

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(115200);
}

void loop() {
  unsigned long now = millis();   // Milliseconds since power-up; read it once per pass
  loops++;

  if (now - lastBlink >= BLINK_MS) {      // Task 1: blink
    lastBlink = now;
    ledState = !ledState;
    digitalWrite(LED_BUILTIN, ledState);
  }

  if (now - lastReport >= REPORT_MS) {    // Task 2: heartbeat
    lastReport = now;
    Serial.print("alive, loop ran about ");
    Serial.print(loops / (REPORT_MS / 1000));
    Serial.println(" times per second");
    loops = 0;
  }
  // You can add tasks 3, 4, 5 here and none of them block the others. Buttons and sensors get written this way from now on
}

#include <Arduino.h>
// Three LEDs, each through 220Ω: red PB0, yellow PB1, green PB10, other ends to GND
const int RED = PB0, YELLOW = PB1, GREEN = PB10;

enum State { S_RED, S_GREEN, S_YELLOW };   // Give a name to "which phase we're in right now"
State state = S_RED;
unsigned long enteredAt = 0;               // When we entered the current state

// How long each state lasts (milliseconds)
unsigned long durationOf(State s) {
  switch (s) {
    case S_RED:    return 3000;
    case S_GREEN:  return 3000;
    case S_YELLOW: return 1000;
  }
  return 1000;
}

void showLights(State s) {
  digitalWrite(RED,    s == S_RED);
  digitalWrite(YELLOW, s == S_YELLOW);
  digitalWrite(GREEN,  s == S_GREEN);
}

void setup() {
  pinMode(RED, OUTPUT); pinMode(YELLOW, OUTPUT); pinMode(GREEN, OUTPUT);
  showLights(state);
  enteredAt = millis();
}

void loop() {
  if (millis() - enteredAt >= durationOf(state)) {   // Time's up for the current state
    if (state == S_RED)         state = S_GREEN;      // Transition table
    else if (state == S_GREEN)  state = S_YELLOW;
    else                        state = S_RED;
    enteredAt = millis();
    showLights(state);
  }
  // The rest of loop is idle and can handle buttons or serial at the same time
}

#include <Arduino.h>
// Button or pulse signal on PB12, other end to GND, internal pull-up. Count once per falling edge
const int PIN = PB12;

volatile uint32_t count = 0;   // volatile: tells the compiler this variable gets changed "behind its back" by the interrupt, so don't optimize it away

void onFalling() {             // Interrupt service routine: keep it as short as possible, no Serial, no delay
  count++;
}

void setup() {
  Serial.begin(115200);
  pinMode(PIN, INPUT_PULLUP);
  // Bind "a falling edge on PB12" to onFalling. FALLING = high to low, RISING = low to high, CHANGE = either
  attachInterrupt(digitalPinToInterrupt(PIN), onFalling, FALLING);
}

void loop() {
  static unsigned long last = 0;
  if (millis() - last >= 1000) {
    last = millis();
    noInterrupts();            // Disable interrupts while reading a multi-byte variable so it can't change halfway through
    uint32_t snapshot = count;
    interrupts();
    Serial.print("Total so far: ");
    Serial.println(snapshot);
  }
}
// Pressing a button by hand will count several times per press; that's bounce, see the "interrupt + millis debounce" snippet

#include <Arduino.h>
// Hardware timer: an independent counter in the chip calls your callback on schedule, without using loop and regardless of how fast loop runs
// The F103 has TIM1~TIM4. TIM1 is advanced, TIM2~4 are general purpose; we use TIM2 here
HardwareTimer timer(TIM2);
volatile uint32_t ticks = 0;

void onTick() {                     // The callback runs in an interrupt: keep it short, no Serial, no delay
  digitalWrite(PC13, !digitalRead(PC13));   // Toggle the onboard LED
  ticks++;
}

void setup() {
  pinMode(PC13, OUTPUT);
  Serial.begin(115200);

  timer.setOverflow(2, HERTZ_FORMAT);   // Overflow 2 times per second = call the callback every 500ms
  // Or timer.setOverflow(500000, MICROSEC_FORMAT);  in microseconds
  timer.attachInterrupt(onTick);
  timer.resume();                       // Start counting. pause() stops it
}

void loop() {
  static uint32_t last = 0;
  if (millis() - last >= 1000) {
    last = millis();
    Serial.print("Timer has fired ");
    Serial.print(ticks);
    Serial.println(" times");
  }
  // loop can delay all it wants; the LED still blinks on time. That's the value of a hardware timer
}

