#include <Arduino.h>
// HC-SR04: VCC→5V, GND→GND, TRIG→PB10, ECHO→PB11
// ECHO outputs a 5V HIGH; PB10/PB11 are 5V-tolerant pins so they can connect directly. Don't use PA0~PA7
const int TRIG = PB10;
const int ECHO = PB11;

void setup() {
  Serial.begin(115200);
  pinMode(TRIG, OUTPUT);
  pinMode(ECHO, INPUT);
  digitalWrite(TRIG, LOW);
}

float readDistanceCm() {
  digitalWrite(TRIG, HIGH);                   // Send a 10-microsecond trigger pulse
  delayMicroseconds(10);
  digitalWrite(TRIG, LOW);

  // Wait for ECHO to go high and measure how long it stays high (microseconds); give up after 30ms
  unsigned long us = pulseIn(ECHO, HIGH, 30000);
  if (us == 0) return -1;                     // Timeout: too far, or not wired right

  // Speed of sound is about 343m/s = 0.0343cm/us; the sound travels there and back, so divide by 2
  return us * 0.0343f / 2.0f;
}

void loop() {
  float d = readDistanceCm();
  if (d < 0) Serial.println("Out of range (>4m) or not connected");
  else {
    Serial.print("Distance: ");
    Serial.print(d, 1);
    Serial.println(" cm");
  }
  delay(100);                                 // At least 60ms between measurements to avoid echo crosstalk
}

#include <Arduino.h>
// Passive buzzer: positive (long leg or marked +) → PA8, negative → GND
// An active buzzer makes only one tone; just digitalWrite it high/low to sound/stop, no tone needed
const int BUZZER = PA8;

// Note frequencies (Hz): do re mi fa so la ti do
const int NOTES[] = {262, 294, 330, 349, 392, 440, 494, 523};

void setup() {
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  for (int i = 0; i < 8; i++) {
    tone(BUZZER, NOTES[i], 200);   // pin, frequency, duration in ms (non-blocking)
    delay(250);                    // Leave a 50ms gap between notes so they sound separate
  }
  noTone(BUZZER);                  // Stop
  delay(500);

  // Alarm sound: alternate between two frequencies
  for (int i = 0; i < 3; i++) {
    tone(BUZZER, 800);  delay(150);
    tone(BUZZER, 1200); delay(150);
  }
  noTone(BUZZER);
  delay(2000);
}

