#include <RTClib.h>
// DS3231 module: VCC→3.3V, GND→GND, SCL/SDA→the board's I2C pins (Blue Pill PB8/PB9 needs setSCL/setSDA)
RTC_DS3231 rtc;

const int ALARM_HOUR = 7, ALARM_MINUTE = 30;   // Daily trigger time
bool firedToday = false;                        // Prevents repeated triggers within the same minute

void setup() {
  Serial.begin(115200);
  if (!rtc.begin()) { Serial.println("DS3231 not found; check the I2C wiring"); while (1) delay(10); }
  if (rtc.lostPower()) {                        // Battery dead or first use: set from the compile time
    Serial.println("RTC lost time; setting from compile time");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  DateTime now = rtc.now();
  char buf[20];
  snprintf(buf, sizeof(buf), "%04d-%02d-%02d %02d:%02d:%02d",
           now.year(), now.month(), now.day(), now.hour(), now.minute(), now.second());
  Serial.println(buf);

  bool isAlarmTime = (now.hour() == ALARM_HOUR && now.minute() == ALARM_MINUTE);
  if (isAlarmTime && !firedToday) {
    firedToday = true;
    Serial.println(">>> Time's up! Put the action here (feed the pet, turn on the light)");
  }
  if (!isAlarmTime) firedToday = false;         // Once that minute has passed, reset so it fires again tomorrow

  Serial.print("Module temperature "); Serial.println(rtc.getTemperature());
  delay(1000);
}

#include <Arduino.h>
// Potentiometer: outer legs to 3.3V and GND, middle leg to PA0
// LED: PA8 → 220Ω → LED → GND
const int POT = PA0;
const int LED = PA8;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);     // Read 0~4095
  analogWriteResolution(8);     // Write 0~255
  pinMode(LED, OUTPUT);
}

void loop() {
  int raw = analogRead(POT);                 // 0~4095

  // Simple smoothing: the new value counts 1/4, the old value 3/4, which removes knob jitter
  static int smooth = 0;
  smooth = (smooth * 3 + raw) / 4;

  int duty = map(smooth, 0, 4095, 0, 255);   // Scale to the PWM range
  duty = (duty * duty) / 255;                // Squared curve so the dim end changes more noticeably
  analogWrite(LED, duty);

  Serial.print(raw);
  Serial.print(" -> ");
  Serial.println(duty);
  delay(20);
}

#include <Arduino.h>
// Photoresistor divider: 3.3V → photoresistor → PA1 (and also) → 10kΩ resistor → GND
// In bright light the photoresistor's resistance drops and PA1's voltage rises; in the dark its resistance rises and PA1's voltage drops
const int LDR = PA1;
const int LED = PC13;
const int DARK_THRESHOLD = 1200;   // Below this counts as dark. Run it once, watch serial, and adjust for your room

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  pinMode(LED, OUTPUT);
}

void loop() {
  long sum = 0;
  for (int i = 0; i < 16; i++) sum += analogRead(LDR);   // Average 16 samples to fight noise
  int light = sum / 16;

  // Add some "hysteresis": below 1200 counts as dark, but it has to go above 1400 to count as bright again, to avoid flicker near the threshold
  static bool dark = false;
  if (!dark && light < DARK_THRESHOLD)        dark = true;
  else if (dark && light > DARK_THRESHOLD + 200) dark = false;

  digitalWrite(LED, dark ? LOW : HIGH);       // PC13 lights on LOW: light on when dark
  Serial.print("light=");
  Serial.print(light);
  Serial.println(dark ? "  dark" : "  bright");
  delay(200);
}

#include <Arduino.h>
#include <IWatchdog.h>
// Independent watchdog (IWDG): a countdown timer you must reset ("feed the dog") regularly.
// Forget to feed it (meaning the program is stuck) and it resets the chip. Once started it can't be stopped until power is cut

void setup() {
  Serial.begin(115200);
  pinMode(PC13, OUTPUT);
  delay(200);
  if (IWatchdog.isReset()) {           // Check whether this boot was caused by the watchdog
    Serial.println("!!! Last reset was the watchdog, so the program hung");
    IWatchdog.clearReset();
  } else {
    Serial.println("Normal power-up");
  }
  IWatchdog.begin(2000000);            // In microseconds: reset if not fed within 2 seconds (max about 32 seconds)
}

void loop() {
  static unsigned long bootMs = millis();
  digitalWrite(PC13, !digitalRead(PC13));
  Serial.print("Running ");
  Serial.print((millis() - bootMs) / 1000);
  Serial.println(" seconds");
  delay(500);
  IWatchdog.reload();                  // Feed the dog: tell it "I'm still alive"

  // Demo: after 10 seconds, deliberately hang in an infinite loop and stop feeding; 2 seconds later you'll see the board reboot itself
  if (millis() - bootMs > 10000) {
    Serial.println("Simulating a hang...");
    while (1) { }
  }
}

