#include <EEPROM.h>
// The STM32 has no real EEPROM; STM32duino emulates one in the last page of Flash. The API is the same as the UNO's EEPROM
// Here we record "how many times the board has been powered on"

struct Settings {
  uint32_t magic;        // Fixed marker to tell whether anything was ever stored (on first use, Flash holds garbage)
  uint32_t bootCount;
  float    calibration;  // Also demonstrates storing a float
};
const uint32_t MAGIC = 0xA5A5C001;
const int ADDR = 0;      // Storage address

void setup() {
  Serial.begin(115200);
  delay(300);

  Settings s;
  EEPROM.get(ADDR, s);                 // Read the bytes starting at ADDR into the struct
  if (s.magic != MAGIC) {              // First time: initialize
    Serial.println("Nothing stored yet, initializing");
    s.magic = MAGIC;
    s.bootCount = 0;
    s.calibration = 1.0f;
  }
  s.bootCount++;
  EEPROM.put(ADDR, s);                 // Write back. On the STM32 this erases and rewrites a whole Flash page, taking tens of milliseconds

  Serial.print("This is power-up #");
  Serial.print(s.bootCount);
  Serial.println(" for this board");
  Serial.print("Calibration ");
  Serial.println(s.calibration);
}

