#include <Arduino.h>
// Button on PB12 to GND, internal pull-up. Catch the falling edge with an interrupt and filter bounce with a timestamp inside the interrupt
const int BTN = PB12;
const unsigned long DEBOUNCE_MS = 50;

volatile uint32_t presses = 0;
volatile unsigned long lastIsrMs = 0;

void onPress() {
  unsigned long now = millis();       // millis can be read inside an interrupt (it just reads a counter)
  if (now - lastIsrMs < DEBOUNCE_MS) return;   // Too soon after the last one: it's bounce, ignore it
  lastIsrMs = now;
  presses++;
}

void setup() {
  Serial.begin(115200);
  pinMode(BTN, INPUT_PULLUP);
  pinMode(PC13, OUTPUT);
  attachInterrupt(digitalPinToInterrupt(BTN), onPress, FALLING);
}

void loop() {
  static uint32_t shown = 0;
  if (presses != shown) {             // Print only when the count changed; loop does nothing else
    shown = presses;
    Serial.print("Button presses: ");
    Serial.println(shown);
    digitalWrite(PC13, !digitalRead(PC13));
  }
  delay(100);                         // A deliberate delay to prove the button isn't affected by loop
}

