#include <Arduino.h>
// Illustrative: PA1 reads a temperature sensor (assumed here to be a linear LM35-type, 10mV/°C), PA8 PWM drives a heater pad (through a MOSFET)
// To use a DS18B20 instead, just replace readTemp(). Target 40°C
const int TEMP_PIN = PA1;
const int HEAT_PIN = PA8;
const float TARGET = 40.0f;

// Three gains: tune only Kp first (too high oscillates, too low never arrives), then add a little Ki to remove steady-state error, and Kd last
float Kp = 20.0f, Ki = 0.5f, Kd = 5.0f;
float integral = 0, lastError = 0;

float readTemp() {
  int raw = analogRead(TEMP_PIN);            // 12-bit
  return raw * 3.3f / 4095.0f * 100.0f;      // LM35: 0.01V/°C
}

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
  pinMode(HEAT_PIN, OUTPUT);
}

void loop() {
  static unsigned long last = 0;
  const float DT = 0.5f;                     // Control period 0.5 seconds
  if (millis() - last < DT * 1000) return;
  last = millis();

  float temp = readTemp();
  float error = TARGET - temp;               // How far off we are
  integral += error * DT;                    // Accumulated error (removes long-term offset)
  integral = constrain(integral, -50, 50);   // Anti-windup: don't let the integral grow without bound
  float derivative = (error - lastError) / DT;   // Rate of change (brake early)
  lastError = error;

  float output = Kp * error + Ki * integral + Kd * derivative;
  int duty = constrain((int)output, 0, 255); // Heating can only be 0~255; there's no "negative heating"
  analogWrite(HEAT_PIN, duty);

  Serial.print(temp); Serial.print(","); Serial.print(TARGET); Serial.print(","); Serial.println(duty);
}

#include <Arduino.h>
#include <Servo.h>
// SG90: brown→GND, red→5V, orange→PA8
Servo sweeper;
const int SERVO_PIN = PA8;
const int STEP_MS = 15;         // 15ms per step; one 0→180 sweep takes about 2.7 seconds

int angle = 0;
int direction = 1;              // +1 heading toward 180, -1 heading toward 0
unsigned long lastStep = 0;

void setup() {
  Serial.begin(115200);
  sweeper.attach(SERVO_PIN);
  sweeper.write(angle);
}

void loop() {
  if (millis() - lastStep >= STEP_MS) {   // Move one degree every 15ms, no delay
    lastStep = millis();
    angle += direction;
    if (angle >= 180) { angle = 180; direction = -1; }   // Turn around at the ends
    if (angle <= 0)   { angle = 0;   direction = 1;  }
    sweeper.write(angle);
  }

  // Here you can read an ultrasonic sensor, a button, or serial at the same time. E.g. a button that freezes it at the current angle:
  // if (digitalRead(PB12) == LOW) direction = 0;
  static unsigned long lastPrint = 0;
  if (millis() - lastPrint >= 500) {
    lastPrint = millis();
    Serial.print("Angle ");
    Serial.println(angle);
  }
}

