#include <Arduino.h>
// HC-05/HC-06 Bluetooth serial module: VCC→5V, GND→GND, TXD→PA3 (board RX), RXD→PA2 (board TX)
// The module's RXD is 3.3V logic; the Blue Pill's TX is 3.3V, a perfect match. A UNO's 5V TX needs a divider
// Install "Serial Bluetooth Terminal" on the phone, pair with PIN 1234 or 0000, send 1 for LED on, 0 for off
// USART2 is the Bluetooth port: RX=PA3, TX=PA2. Serial stays on PA9/PA10 for the computer
#if defined(ARDUINO_API_VERSION)  // From STM32duino 3.x the serial class is called Uart
Uart BT(PA3, PA2);
#else                             // STM32duino 2.x calls it HardwareSerial
HardwareSerial BT(PA3, PA2);
#endif

void setup() {
  Serial.begin(115200);           // Computer
  BT.begin(9600);                 // Bluetooth module default 9600 (some HC-05s are 38400; check the module's docs)
  pinMode(PC13, OUTPUT);
  digitalWrite(PC13, HIGH);
  Serial.println("Waiting for Bluetooth commands...");
}

void loop() {
  if (BT.available()) {
    char c = BT.read();
    Serial.print("Received: ");
    Serial.println(c);
    if (c == '1') {
      digitalWrite(PC13, LOW);    // On
      BT.println("LED ON");       // Reply to the phone
    } else if (c == '0') {
      digitalWrite(PC13, HIGH);
      BT.println("LED OFF");
    }
  }
  // Forward anything typed on the computer's serial to the phone, handy for debugging
  if (Serial.available()) BT.write(Serial.read());
}

