void connectWiFi() {
  Serial.print("Connecting to ");
  Serial.println(WIFI_SSID);
  WiFi.mode(WIFI_STA);                     // Act as a client joining the router (not as a hotspot)
  WiFi.begin(WIFI_SSID, WIFI_PASS);

