#include <Arduino.h>
#include <SPI.h>
// Short PA7(MOSI) to PA6(MISO) with one jumper wire. Whatever byte goes out should come straight back
// SPI1: SCK PA5 / MISO PA6 / MOSI PA7; chip select can be any ordinary GPIO
const int CS_PIN = PA4;

void setup() {
  Serial.begin(115200);
  pinMode(CS_PIN, OUTPUT);
  digitalWrite(CS_PIN, HIGH);        // Chip select high = not selected, low = selected
  SPI.begin();                       // Initialize SPI1, default PA5/PA6/PA7
}

void loop() {
  // Bundle speed, bit order, and mode: 1MHz, most significant bit first, mode 0 (most chips use mode 0)
  SPI.beginTransaction(SPISettings(1000000, MSBFIRST, SPI_MODE0));
  digitalWrite(CS_PIN, LOW);         // Select the "device" (there isn't one here, but follow the procedure)

  uint8_t sent[] = {0x55, 0xAA, 0x12, 0x34};
  int ok = 0;
  for (int i = 0; i < 4; i++) {
    uint8_t got = SPI.transfer(sent[i]);   // SPI is full duplex: send a byte and receive one at the same time
    Serial.print("Sent 0x"); Serial.print(sent[i], HEX);
    Serial.print(" got 0x"); Serial.print(got, HEX);
    Serial.println(got == sent[i] ? "  OK" : "  MISMATCH");
    if (got == sent[i]) ok++;
  }

  digitalWrite(CS_PIN, HIGH);        // Release
  SPI.endTransaction();
  Serial.println(ok == 4 ? "SPI loopback passed" : "Loopback failed: check the PA6-PA7 jumper");
  delay(2000);
}
// With a real device: remove the jumper, MOSI→device DI/SDI, MISO→device DO/SDO, SCK→CLK, CS→CS/SS
